const items = $input.all();
const results = [];

for (const item of items) {
  const raw = item.json;
  const competitions = Array.isArray(raw) ? raw : (raw.competitions || [raw]);

  for (const comp of competitions) {
    if (!comp.id && !comp.ref) continue;
    results.push({
      json: {
        id: `kaggle_${comp.id || comp.ref}`,
        source: 'Kaggle',
        title: comp.title || 'Kaggle Competition',
        organization: comp.organizationName || 'Kaggle',
        location: 'Remote / Global',
        skills: ['Machine Learning', 'Data Science', 'Python', 'AI'],
        postedDate: comp.enabledDate || new Date().toISOString(),
        deadline: comp.deadline || null,
        applyLink: comp.url || `https://www.kaggle.com/competitions/${comp.ref}`,
        detailsURL: comp.url || `https://www.kaggle.com/competitions/${comp.ref}`,
        type: 'competition',
        canAutoApply: false
      }
    });
  }
}

return results;

const items = $input.all();
const results = [];

for (const item of items) {
  const raw = item.json;
  const hackathons = raw.hackathons || (Array.isArray(raw) ? raw : [raw]);

  for (const h of hackathons) {
    if (!h.id && !h.title) continue;
    const themes = (h.themes || []).map(t => typeof t === 'string' ? t : (t.name || t.toString()));
    results.push({
      json: {
        id: `devpost_${h.id}`,
        source: 'Devpost',
        title: h.title,
        organization: h.organization_name || 'Devpost Partner',
        location: h.displayed_location?.location || 'Online',
        skills: themes.length ? themes : ['Hackathon', 'AI', 'Coding'],
        postedDate: new Date().toISOString(),
        deadline: h.submission_period_dates || null,
        applyLink: h.url,
        detailsURL: h.url,
        type: 'hackathon',
        canAutoApply: false
      }
    });
  }
}

return results;

const items = $input.all();
const results = [];

for (const item of items) {
  const raw = item.json;
  const events = raw.response || (Array.isArray(raw) ? raw : [raw]);

  for (const e of events) {
    if (!e.title) continue;
    const rawId = (e.title || '').replace(/[^a-zA-Z0-9]+/g, '_').toLowerCase();
    results.push({
      json: {
        id: `hackerearth_${rawId}`,
        source: 'HackerEarth',
        title: e.title,
        organization: e.is_hackerearth ? 'HackerEarth' : 'HackerEarth Partner',
        location: 'Online',
        skills: ['Coding', 'Algorithms', 'Hackathon', 'AI', 'Machine Learning'],
        postedDate: e.start_utc_tz || new Date().toISOString(),
        deadline: e.end_tz || e.end_date || null,
        applyLink: e.url,
        detailsURL: e.url,
        type: 'challenge',
        canAutoApply: false
      }
    });
  }
}

return results;

const targetSkills = ['python', 'ml', 'ai', 'machine learning', 'hackathon', 'data science', 'backend', 'fullstack', 'pytorch', 'coding'];
const now = new Date();

const items = $input.all();
const filtered = [];

for (const item of items) {
  const data = item.json;
  if (!data || !data.id) continue;

  // Check Skill Match
  const haystack = `${data.title} ${data.organization || ''} ${(data.skills || []).join(' ')}`.toLowerCase();
  const matchedSkill = targetSkills.find(skill => haystack.includes(skill));

  if (matchedSkill) {
    filtered.push({
      json: {
        ...data,
        matchedKeyword: matchedSkill
      }
    });
  }
}

return filtered;

const staticData = $getWorkflowStaticData('global');
staticData.seenIds = staticData.seenIds || [];

const items = $input.all();
const newItems = [];
const seenSet = new Set(staticData.seenIds);

for (const item of items) {
  const id = item.json.id;
  if (id && !seenSet.has(id)) {
    seenSet.add(id);
    newItems.push(item);
  }
}

const updatedList = Array.from(seenSet);
if (updatedList.length > 2000) {
  staticData.seenIds = updatedList.slice(updatedList.length - 2000);
} else {
  staticData.seenIds = updatedList;
}

return newItems;

const items = $input.all();
if (!items.length) return [];

const rows = items.map(item => {
  const d = item.json;
  return `• *[${d.source}]* <${d.applyLink}|${d.title}> at *${d.organization}* (${d.location}) - Match: \`${d.matchedKeyword}\``;
});

const slackText = `🎯 *Found ${items.length} New Opportunities Matching Your Profile:*\n\n` + rows.join('\n');

return [{
  json: {
    count: items.length,
    summaryMarkdown: slackText,
    opportunities: items.map(i => i.json)
  }
}];
